    kl("\u0627\u0644\u0646\u0635\u0631 \u0644\u0627 \u064a\u0643\u062a\u0645\u0644 \u0628\u0627\u0644\u0639\u062f\u062f \u0648\u062d\u062f\u0647\u061b \u0641\u0641\u064a \u0646\u0647\u0627\u0648\u0646\u062f \u0648\u0627\u062c\u0647 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u062c\u064a\u0634\u0627\u064b \u0623\u0642\u0644 \u0645\u0639 \u062a\u0643\u062a\u0644 \u0648\u062b\u0628\u0627\u062a\u060c ", TP, "\u061b ", YT, " \u0630\u0644\u0643 \u0625\u0644\u0649 \u0627\u0644\u062a\u0648\u0643\u0644 \u0645\u0639 \u0627\u0644\u0623\u0633\u0628\u0627\u0628 \u0641\u064a \u0643\u0644 \u0645\u062c\u0627\u0644 \u0645\u0646 \u0645\u062c\u0627\u0644\u0627\u062a \u0627\u0644\u062d\u064a\u0627\u0629."),
    kl("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u064a\u0633\u0628\u0642 \u0627\u0644\u0639\u0646\u0627\u0621\u061b \u0641\u0627\u062e\u062a\u064a\u0627\u0631 \u0645\u0648\u0642\u0639 \u0646\u0647\u0627\u0648\u0646\u062f \u0648\u0627\u0644\u0627\u0633\u062a\u0639\u0627\u0646\u0629 \u0628\u0627\u0644\u062a\u0643\u062a\u0644 \u0643\u0627\u0646\u0627 \u0645\u0646 \u0623\u0633\u0628\u0627\u0628 \u0627\u0644\u0646\u0635\u0631\u060c ", YS, " \u0645\u0646\u0647 \u0623\u0646 \u0627\u0644\u0628\u0635\u064a\u0631\u0629 \u0644\u0627 \u062a\u0639\u0646\u064a \u0627\u0644\u062a\u0647\u0648\u0631 \u0628\u0644 \u0627\u0644\u062a\u062f\u0628\u064a\u0631\u061b ", MR, "."),
    kl("\u0627\u0644\u0641\u062a\u062d \u0627\u0644\u062d\u0642\u064a\u0642\u064a \u064a\u062d\u062a\u0627\u062c \u0625\u062f\u0627\u0631\u0629\u061b \u0644\u0645 \u064a\u0643\u0646 \u0627\u0646\u062a\u0635\u0627\u0631 \u0646\u0647\u0627\u0648\u0646\u062f \u0639\u0631\u064a\u0636\u0627\u064b \u0628\u0644 \u0628\u0646\u0627\u0621 \u0644\u0644\u0625\u062f\u0627\u0631\u0629 \u0648\u0627\u0644\u0639\u062f\u0644\u060c ", YD, " \u0623\u0646 \u0627\u0644\u0628\u0642\u0627\u0621 \u0628\u0627\u0644\u062d\u0642 \u0623\u0639\u0645\u0649 \u0645\u0646 \u0627\u0644\u062a\u0648\u0633\u0639 \u0628\u0644\u0627 \u0636\u0648\u0627\u0628\u0637\u061b ", IQ, "."),
    kl("\u0627\u0644\u062b\u0628\u0627\u062a \u0639\u0646\u062f \u0627\u0644\u0627\u0628\u062a\u0644\u0627\u0621 \u0641\u0636\u064a\u0644\u0629\u061b \u0641\u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u0641\u064a \u0646\u0647\u0627\u0648\u0646\u062f \u062b\u0628\u062a\u0648\u0627 \u0631\u063a\u0645 \u0627\u0644\u0636\u064a\u0642 \u0648\u0643\u062b\u0631\u0629 \u0627\u0644\u0645\u0641\u0627\u062c\u0626\u0627\u062a\u060c ", TP, "\u061b ", YT, " \u0630\u0644\u0643 \u0625\u0644\u0649 ", SK, " \u0645\u0639 \u0627\u0644\u0627\u0639\u062a\u0645\u0627\u062f \u0639\u0644\u0649 \u0648\u0639\u062f \u0627\u0644\u0644\u0647."),
