def validate(stories):
    errors = []
    for s in stories:
        if len(s["summary"]) < 170:
            errors.append(f"id {s['id']} summary too short: {len(s['summary'])}")
        if len(s["full_content"]) < 900:
            errors.append(f"id {s['id']} content too short: {len(s['full_content'])}")
        for i, l in enumerate(s["key_lessons"]):
            if len(l) < 120:
                errors.append(f"id {s['id']} lesson {i+1} too short: {len(l)}")
    return errors

errors = validate(stories)
if errors:
    for e in errors:
        print('ERROR:', e)
    raise SystemExit(1)

